,\"div\",null,{\"className\":\"flex justify-center px-4 md:px-8 mt-6\",\"children\":[\"$\",\"a\",null,{\"href\":\"https://dashboard.simpleanalytics.com/?utm_source=vedabase.io&utm_content=badge\",\"referrerPolicy\":\"origin\",\"target\":\"_blank\",\"children\":[\"$\",\"picture\",null,{\"children\":\"$37\"}]}]}]]}]\n"])self.__next_f.push([1,"32:[\"$\",\"em\",null,{\"children\":\"veda\"}]\n33:[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"knows\"}}]\n34:[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-saḥ\",{\"href\":\"/en/search/synonyms/?original=saḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"saḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"he\"}}],\"; \"]}]\n35:[\"$\",\"span\",\"wfwundefined-14\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-veda\",{\"href\":\"/en/search/synonyms/?original=veda\",\"children\":[\"$\",\"em\",null,{\"children\":\"veda\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-vit\",{\"href\":\"/en/search/synonyms/?original=vit\",\"children\":[\"$\",\"em\",null,{\"children\":\"vit\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the knower of the Vedas.\"}}],\".\"]}]\n38:T700,"])self.__next_f.push([1,"This tree, being the reflection of the real tree, is an exact replica. Everything is there in the spiritual world. The impersonalists take Brahman to be the root of this material tree, and from the root, according to Sāṅkhya philosophy, come prakṛti, puruṣa, then the three guṇas, then the five gross elements (pañca-mahā-bhūta), then the ten senses (daśendriya), mind, etc. In this way they divide up the whole material world into twenty-four elements. If Brahman is the center of all manifestations, then this material world is a manifestation of the center by 180 degrees, and the other 180 degrees constitute the spiritual world. The material world is the perverted reflection, so the spiritual world must have the same variegatedness, but in reality. The prakṛti is the external energy of the Supreme Lord, and the puruṣa is the Supreme Lord Himself, and that is explained in Bhagavad-gītā. Since this manifestation is material, it is temporary. A reflection is temporary, for it is sometimes seen and sometimes not seen. But the origin from whence the reflection is reflected is eternal. The material reflection of the real tree has to be cut off. When it is said that a person knows the Vedas, it is assumed that he knows how to cut off attachment to this material world. If one knows that process, he actually knows the Vedas. One who is attracted by the ritualistic formulas of the Vedas is attracted by the beautiful green leaves of the tree. He does not exactly know the purpose of the Vedas. The purpose of the Vedas, as disclosed by the Personality of Godhead Himself, is to cut down this reflected tree and attain the real tree of the spiritual world."])self.__next_f.push([1,"36:[\"$\",\"$L2a\",\"child-3993\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:4\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$38\"}}]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a3405a767b5ef501'',t:''MTc4ODIyNDU4Nw==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''head'')[0].appendChild(d)}}if(document.body){var a=document.createElement(''iframe'');a.height=1;a.width=1;a.style.position=''absolute'';a.style.top=0;a.style.left=0;a.style.border=''none'';a.style.visibility=''hidden'';document.bo