नान्तो न चादिर्न च सम्प्रतिष्ठा ।
अश्वत्थमेनं सुविरूढमूल-
मसङ्गशस्त्रेण दृढेन छित्त्वा ॥ ३ ॥
तत: पदं तत्परिमार्गितव्यं
यस्मिन्गता न निवर्तन्ति भूय: ।
तमेव चाद्यं पुरुषं प्रपद्ये
यत: प्रवृत्ति: प्रसृता पुराणी ॥ ४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4003,\"bb\":3521,\"url_path\":\"/en/library/bg/15/3-4/b3521/\",\"body_value\":\"na rūpam asyeha tathopalabhyate
nānto na cādir na ca sampratiṣṭhā
aśvattham enaṁ su-virūḍha-mūlam
asaṅga-śastreṇa dṛḍhena chittvā\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4004,\"bb\":3522,\"url_path\":\"/en/library/bg/15/3-4/b3522/\",\"body_value\":\"tataḥ padaṁ tat parimārgitavyaṁ
yasmin gatā na nivartanti bhūyaḥ
tam eva cādyaṁ puruṣaṁ prapadye
yataḥ pravṛttiḥ prasṛtā purāṇī\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4005,\"bb\":3523,\"url_path\":\"/en/library/bg/15/3-4/b3523/\",\"shadow_value\":\"$25\",\"word_for_word_value\":[{\"word\":\"na\",\"translation\":\"not\"},{\"word\":\"rūpam\",\"translation\":\"the form\"},{\"word\":\"asya\",\"translation\":\"of this tree\"},{\"word\":\"iha\",\"translation\":\"in this world\"},{\"word\":\"tathā\",\"translation\":\"also\"},{\"word\":\"upalabhyate\",\"translation\":\"can be perceived\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"antaḥ\",\"translation\":\"end\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"ādiḥ\",\"translation\":\"beginning\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"sampratiṣṭhā\",\"translation\":\"the foundation\"},{\"word\":\"aśvattham\",\"translation\":\"banyan tree\"},{\"word\":\"enam\",\"translation\":\"this\"},{\"word\":\"su-virūḍha\",\"translation\":\"strongly\"},{\"word\":\"mūlam\",\"translation\":\"rooted\"},{\"word\":\"asaṅga-śastreṇa\",\"translation\":\"by the weapon of detachment\"},{\"word\":\"dṛḍhena\",\"translation\":\"strong\"},{\"word\":\"chittvā\",\"translation\":\"cutting\"},{\"word\":\"tataḥ\",\"translation\":\"thereafter\"},{\"word\":\"padam\",\"translation\":\"situation\"},{\"word\":\"tat\",\"translation\":\"that\"},{\"word\":\"parimārgitavyam\",\"translation\":\"has to be searched out\"},{\"word\":\"yasmin\",\"translation\":\"where\"},{\"word\":\"gatāḥ\",\"translation\":\"going\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"nivartanti\",\"translation\":\"they come back\"},{\"word\":\"bhūyaḥ\",\"translation\":\"again\"},{\"word\":\"tam\",\"translation\":\"to Him\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"ādyam\",\"translation\":\"original\"},{\"word\":\"puruṣam\",\"translation\":\"the Personality of Godhead\"},{\"word\":\"prapadye\",\"translation\":\"surrender\"},{\"word\":\"yataḥ\",\"translation\":\"from whom\"},{\"word\":\"pravṛttiḥ\",\"translation\":\"the beginning\"},{\"word\":\"prasṛtā\",\"translation\":\"extended\"},{\"word\":\"purāṇi\",\"translation\":\"very old\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4006,\"bb\":3524,\"url_path\":\"/en/library/bg/15/3-4/b3524/\",\"body_value\":\"The real form of this tree cannot be perceived in this world. No one can understand where it ends, where it begins, or where its foundation is. But with determination one must cut down this strongly rooted tree with the weapon of detachment. Thereafter, one must seek that place from which, having gone, one never returns, and there surrender to that Supreme Personality of Godhead from whom everything began and from whom everything has extended since time immemorial.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4007,\"bb\":3525,\"url_path\":\"/en/library/bg/15/3-4/b3525/\",\"body_value\":\"It is now clearly stated that the real form of this banyan tree cannot be understood in this material world. Since the root is upwards, the extension of the real tree is at the other end. When entangled with the material expansions of the tree, one cannot see how far the tree extends, nor can one see the beginning of this tree. Yet one has to find out the cause. “I am the son of my father, my father is the son of such-and-such a person, etc.” By searching in this way, one comes to Brahmā, who is generated by the Garbhodaka-śāyī Viṣṇu. Finally, in this way, when one reaches the Supreme Personality of Godhead, that is the end of research work. One has to search out that origin of this tree, the Supreme Personality of Godhead, through the association of persons who are in knowledge of that Supreme Personality of Godhead. Then by understanding one becomes gradually detached from this false reflection of reality, and by knowledge one can cut off the connection and actually become situated in the real tree.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4008,\"bb\":3526,\"url_path\":\"/en/library/bg/15/3-4/b3526/\",\"body_value\":\"$26\"}]}],\"short_title\":\"Bg. 15.3-4\",\"medium_title\":\"Bhagavad-gītā As It Is 15.3-4\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L27\",\"$L28\",\"$L29\"]}]\n"])self.__next_f.push([1,"2b:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n31:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n27:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null